question:
Lời gọi cuối cùng trả về gì?
`function hash(key, len) {
  let total = 0;
  for (let i = 0; i < key.length; i++) {
    const value = key.charCodeAt(i) - 96;
    total = (total * 31 + value) % len;
  }
  return total;
}
hash("A", 53); // "A" is 65`

